3	import (
4		"log/slog"
5	
6		"github.com/pkg/errors"
7	)
8	
9	type asyncEmailRequest struct {
10		config  *Config
11		message *Message
12	}
13	
14	var asyncEmailQueue = make(chan asyncEmailRequest, 128)
15	
16	func init() {
17		for range 2 {
18			go func() {
19				for request := range asyncEmailQueue {
20					if err := Send(request.config, request.message); err != nil {
21						recipients := ""
22						if request.message != nil && len(request.message.To) > 0 {
23							recipients = request.message.To[0]
24							if len(request.message.To) > 1 {
25								recipients += " and others"
26							}
27						}
28	
29						slog.Warn("Failed to send email asynchronously",
30							slog.String("recipients", recipients),
31							slog.Any("error", err))
32					}
33				}
34			}()
35		}
36	}
37	
38	// Send sends an email synchronously.
39	// Returns an error if the email fails to send.
40	func Send(config *Config, message *Message) error {
41		if config == nil {
42			return errors.New("email configuration is required")
43		}
44		if message == nil {
45			return errors.New("email message is required")
46		}
47	
48		client := NewClient(config)
49		return client.Send(message)
50	}
51	
52	// SendAsync sends an email asynchronously.
53	// It enqueues the message for bounded asynchronous sending and does not wait for the response.
54	// Any errors are logged but not returned.
55	func SendAsync(config *Config, message *Message) {
56		select {
57		case asyncEmailQueue <- asyncEmailRequest{config: config, message: message}:
58		default:
59			slog.Warn("Dropped email because the async queue is full")
60		}
61	}
