16	func GetImage(urlStr string) (*Image, error) {
17		if _, err := url.Parse(urlStr); err != nil {
18			return nil, err
19		}
20	
21		response, err := http.Get(urlStr)
22		if err != nil {
23			return nil, err
24		}
25		defer response.Body.Close()
26	
27		mediatype, err := getMediatype(response)
28		if err != nil {
29			return nil, err
30		}
31		if !strings.HasPrefix(mediatype, "image/") {
32			return nil, errors.New("wrong image mediatype")
33		}
34	
35		bodyBytes, err := io.ReadAll(response.Body)
36		if err != nil {
37			return nil, err
38		}
39	
40		image := &Image{
